import { ITaskRepository } from "../domain/ITaskRepository";
import { IProjectRepository } from "../domain/IProjectRepository";
import { TaskDTO } from "./TaskDTO";

export class ListTasksUseCase {
  constructor(
    private readonly taskRepository: ITaskRepository,
    private readonly projectRepository: IProjectRepository,
  ) {}

  execute(
    projectId: string,
    status?: string,
    assigneeId?: string,
  ): TaskDTO[] {
    const project = this.projectRepository.findById(projectId);
    if (!project) {
      throw new Error(`Project with id ${projectId} not found`);
    }

    let tasks = this.taskRepository.findByProjectId(projectId);

    if (status) {
      tasks = tasks.filter((task) => task.getStatus().getValue() === status);
    }

    if (assigneeId) {
      tasks = tasks.filter((task) => task.getAssigneeId() === assigneeId);
    }

    return tasks.map((task) => ({
      id: task.getId(),
      projectId: task.getProjectId(),
      title: task.getTitle(),
      description: task.getDescription(),
      status: task.getStatus().getValue(),
      dueDate: task.getDueDate() ? task.getDueDate()!.toISOString() : null,
      assigneeId: task.getAssigneeId(),
    }));
  }
}

